import { useEffect, useState } from 'react';
import { auth as authApi } from '@/api/endpoints.js';
import { ApiError, isApiError } from '@/api/errors.js';
import { Icon } from '@/components/ui/Icon.js';
import { getMeta, setMeta } from '@/db/schema.js';
import { t } from '@/i18n/index.js';
import { useAuth } from './session.js';
import styles from './VerifyBanner.module.css';

/** How long a dismissed banner stays away: until about this time tomorrow. */
const SNOOZE_MS = 24 * 60 * 60 * 1000;

/**
 * A quiet line at the top of Today while the address is unconfirmed, with
 * the one action that helps. It disappears on its own once the profile
 * refresh sees the confirmation, and can be put away for a day by someone
 * who cannot reach their inbox right now.
 */
export function VerifyBanner(): React.JSX.Element | null {
  const user = useAuth((state) => state.user);
  const refreshUser = useAuth((state) => state.refreshUser);
  const [note, setNote] = useState<string | undefined>();
  const [busy, setBusy] = useState(false);
  // Hidden until the snooze has been read, so the banner never flashes.
  const [snoozed, setSnoozed] = useState(true);

  useEffect(() => {
    let alive = true;
    void getMeta('verifySnoozedUntil').then((until) => {
      if (alive) setSnoozed(until !== null && until > Date.now());
    });
    return () => {
      alive = false;
    };
  }, []);

  if (user === null || user.emailVerified || snoozed) return null;

  const snooze = (): void => {
    setSnoozed(true);
    void setMeta('verifySnoozedUntil', Date.now() + SNOOZE_MS);
  };

  const resend = (): void => {
    setBusy(true);
    authApi
      .resendVerification()
      .then(() => {
        setNote(t('auth.verifyResent'));
      })
      .catch((cause: unknown) => {
        if (isApiError(cause, 'offline')) setNote(t('error.offline'));
        else if (cause instanceof ApiError && cause.code === 'rate_limited')
          setNote(t('auth.verifyResendLater'));
        else if (cause instanceof ApiError && cause.code === 'mail_unavailable')
          setNote(t('auth.verifyMailUnavailable'));
        else if (cause instanceof ApiError && cause.code === 'already_verified') void refreshUser();
        else setNote(t('error.generic'));
      })
      .finally(() => {
        setBusy(false);
      });
  };

  return (
    <aside className={styles.banner} aria-live="polite">
      <p className={styles.text}>{note ?? t('auth.verifyBanner', { email: user.email })}</p>
      <div className={styles.actions}>
        {note === undefined && (
          <button type="button" className={styles.action} onClick={resend} disabled={busy}>
            {t('auth.verifyResend')}
          </button>
        )}
        <button type="button" className={styles.dismiss} onClick={snooze} aria-label={t('auth.verifyLater')}>
          <Icon name="close" size={16} weight={2} />
        </button>
      </div>
    </aside>
  );
}
