/**
 * Today's moment: things that happened while the learner was away (a
 * freeze that saved the streak, a trial that started, a year since the
 * first word) and a words milestone a save reached today. Decided once per
 * visit, from local reads, and claimed on the server before it is shown,
 * so no other device shows it too. The hero waits for it only when there
 * is something to claim; a takeover or a toast lands over the page and
 * never moves it. The deciding code (`today.ts`) is its own chunk, loaded
 * once Today's reads have landed, so it is off the first paint.
 */
import { useEffect, useState } from 'react';
import type { LanguageCode } from '@lexpad/core';
import type { StoredCelebrate } from '@/db/schema.js';
import { useBilling } from '@/features/billing/state.js';
import type { MomentCopy } from './copy.js';
import type { Pick } from './moments.js';
import type { TodayDecision } from './today.js';

export interface TodayMomentInput {
  /** Local reads have landed (Today's data and the streak freeze). */
  loaded: boolean;
  today: number;
  doneToday: number;
  streak: number;
  frozenDays: ReadonlySet<number>;
  notebook: { targetLang: LanguageCode; meaningLang: LanguageCode } | undefined;
  /** The plan was in hand as this visit began (a trial moment never arrives late). */
  planAtStart: boolean;
  view: { on: boolean; state: StoredCelebrate | null; synced: boolean; ready: boolean };
}

export interface TodayMoment {
  ready: boolean;
  pick: Pick;
  main?: MomentCopy | undefined;
  line?: MomentCopy | undefined;
}

/** No moment (the engine's NOTHING, written out so the engine stays off the first paint). */
const NOTHING: Pick = { spent: [] };
const NONE: TodayMoment = { ready: true, pick: NOTHING };
const WAITING: TodayMoment = { ready: false, pick: NOTHING };

/** Today's moment for this visit; `ready` false until it is known. */
export function useTodayMoment(input: TodayMomentInput): TodayMoment {
  const billing = useBilling((s) => s.state);
  const [result, setResult] = useState<TodayDecision | undefined>(undefined);
  const { loaded, view } = input;
  const off = view.ready && !view.on;
  const unsettled = view.ready && view.on && view.state === null;

  useEffect(() => {
    if (result !== undefined || !loaded || !view.ready || off || view.state === null) return;
    const alive = { current: true };
    // Loaded only now, once Today's own reads have landed and drawn: never
    // in the way of the first frame.
    void import('./today.js')
      .then((module) =>
        module.decideToday({
          today: input.today,
          doneToday: input.doneToday,
          streak: input.streak,
          frozenDays: [...input.frozenDays],
          notebook: input.notebook,
          billing: input.planAtStart ? billing : null,
        }),
      )
      .catch(() => ({ pick: NOTHING }))
      .then((decided) => {
        if (alive.current) setResult(decided);
      });
    return () => {
      alive.current = false;
    };
    // Decided once per visit, when everything it reads has landed.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [loaded, view.ready, off, view.state === null, result]);

  // Off, or nothing to settle a baseline from yet (never synced): no moment.
  if (off || (unsettled && !view.synced)) return NONE;
  if (result === undefined) return WAITING;
  return { ready: true, pick: result.pick, main: result.main, line: result.line };
}
