import { lazy, Suspense, useEffect, useRef, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { directionOf, type LanguageCode } from '@lexpad/core';
import { Icon, type IconName } from '@/components/ui/Icon.js';
import { Ring } from '@/components/ui/Ring.js';
import { ringFraction } from '@/components/ui/motionPrefs.js';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { hasQueued } from '@/db/repo.js';
import { greeting } from '@/lib/format.js';
import { useLiveQuery } from '@/lib/useLiveQuery.js';
import { useKeepScroll } from '@/lib/useKeepScroll.js';
import { useCurrentDay } from '@/lib/useCurrentDay.js';
import { useCanSpeak } from '@/lib/useCanSpeak.js';
import { useAuth } from '@/features/auth/session.js';
import { VerifyBanner } from '@/features/auth/VerifyBanner.js';
import { UpdateBanner } from './UpdateBanner.js';
import { ReminderBanner } from './ReminderBanner.js';
import { NudgeSlot } from './NudgeSlot.js';
import { StartChip } from '@/features/getstarted/StartChip.js';
import { Bell } from '@/features/inbox/Bell.js';
import { NotebookChip } from '@/features/notebook/NotebookChip.js';
import { LANGUAGE_NAMES } from '@/features/settings/data.js';
import { FREEZE_OFF, loadFreeze, type FreezeView } from '@/features/streak/data.js';
import { StreakFreezeSheet } from '@/features/streak/StreakFreezeSheet.js';
import streakStyles from '@/features/streak/Streak.module.css';
import { GAMES_PATH } from '@/features/modes/data.js';
import { useOpenModes } from '@/features/modes/useOpenModes.js';
import { SCHEDULE_FOCUS, settingsPath } from '@/features/settings/paths.js';
import { loadToday, WEEK_DAYS, type TodayData } from './data.js';
import {
  NO_OFFERS,
  loadSrsOffers,
  putCapOfferAway,
  putSmartInviteAway,
  type SrsOffers,
} from './srsOffers.js';
import { lastPractisedBefore, markComeback } from '@/features/learn/state.js';
import { DECKS_TILE_WORDS, SMALL_NOTEBOOK_WORDS, pickTip, wantsComeback } from '@/features/learn/tips.js';
import { useHeldTip, useLearn } from '@/features/learn/useLearn.js';
import { SmartInvite } from './SmartInvite.js';
import { Upgrade } from '@/features/billing/Upgrade.js';
import { trialDate } from '@/features/billing/trial.js';
import { TrialCard } from './TrialCard.js';
import { markTrialEndingShown, useTrialMoments } from './useTrial.js';
import { useBilling } from '@/features/billing/state.js';
import { Announce } from '@/features/celebrate/Announce.js';
import { MomentLine } from '@/features/celebrate/MomentLine.js';
import { noteChip } from '@/features/celebrate/view.js';
import { useCelebrate } from '@/features/celebrate/useCelebrate.js';
import { useTodayMoment } from '@/features/celebrate/useTodayMoment.js';
import styles from './Today.module.css';

const EMPTY: TodayData = {
  notebook: undefined,
  counts: {
    due: 0,
    new: 0,
    starred: 0,
    struggling: 0,
    confusables: 0,
    tricky: 0,
    mastered: 0,
    total: 0,
  },
  week: [],
  streak: 0,
  streakActive: false,
  topics: [],
  levels: [],
  kinds: [],
  mastered: 0,
  today: 0,
  recent: [],
  started: 0,
  doneToday: 0,
  weekTotal: 0,
  boxes: [0, 0, 0, 0, 0],
  topicCount: 0,
  sessionCap: 0,
  practiceScope: 'notebook',
  notebooks: 0,
  held: 0,
  backlog: false,
  nextDue: undefined,
  notDue: false,
};

/**
 * The longest Today holds what sits below the card place while that place
 * settles. The reads behind it are local and land in a few frames; this
 * bound only matters if one never does, and then the page is drawn anyway.
 */
const BELOW_HOLD_MS = 1500;

const BOX_CLASS = [styles.box1, styles.box2, styles.box3, styles.box4, styles.box5];
/**
 * How many recent words the row on Today shows.
 *
 * Three, not two: two cards on a phone leave a row that looks like it lost
 * one, and the headwords still fit — they are one word each, which is what
 * a headword is. Anything longer truncates, which a card of a word must
 * never do, so the meaning underneath is the part that gives way.
 */
const RECENT_SHOWN = 3;

const WEEKDAYS = ['S', 'M', 'T', 'W', 'T', 'F', 'S'] as const;

/** The celebration sheet, its own chunk: loaded only when a takeover fires on Today. */
const Takeover = lazy(() => import('@/features/celebrate/Takeover.js'));
/** A moment's toast on Today (a words milestone), also its own chunk. */
const MomentToast = lazy(() =>
  import('@/features/celebrate/MomentToast.js').then((module) => ({ default: module.MomentToast })),
);

/**
 * Where the day's ring stood when this run of the app last drew it, so it
 * fills from there on the next visit rather than from empty every time.
 * Per run, like the trial's held moments: a fresh start draws it as it is.
 */
const ringDrawn: { day: number; fraction: number } = { day: -1, fraction: 0 };

/**
 * Today: the greeting, the hero with the day's plan, the newest entries,
 * the focused-practice decks, the AI card, a progress teaser and the week
 * strip — in the prototype's order and to its measurements.
 */
export function Today(): React.JSX.Element {
  const navigate = useNavigate();
  const now = useCurrentDay();
  const data = useLiveQuery(() => loadToday(now), EMPTY, [now]);
  // SRS v2 streak freeze: off (the default) leaves the chip and the week as they were.
  // An async querier, so Dexie follows every read past the first await:
  // turning freeze on from the sheet must redraw it here, in place.
  const freezeRead = useLiveQuery<FreezeView | null>(async () => loadFreeze(data.today), null, [data.today]);
  const freeze = freezeRead ?? FREEZE_OFF;
  const [freezeOpen, setFreezeOpen] = useState(false);
  // SRS v2 access: the games get a door of their own here once any can run,
  // and two offers wait for the moment they help. All silent with the flag off.
  const { view: modesView, open: games } = useOpenModes();
  // Showing one notebook, Today has just counted its words: the offers use
  // those counts rather than reading the notebook again. A limit is not set
  // when the daily-limit line can show, so `counts.due` is every due word.
  const counted =
    data.practiceScope === 'notebook' && data.notebook !== undefined
      ? { started: data.started, due: data.counts.due }
      : undefined;
  const offersRead = useLiveQuery<SrsOffers | null>(
    async () => loadSrsOffers(data.notebook, data.today, counted),
    null,
    [data.notebook, data.today, counted?.started, counted?.due],
  );
  const offers = offersRead ?? NO_OFFERS;
  // The new learner's journey (SRS v2): what the hero says when nothing is
  // due, the day-2 line and the welcome back. All silent with the feature off.
  const learn = useLearn();
  // Celebrations (features/celebrate): what happened while away, and a
  // words milestone reached today; one moment a visit, claimed on the
  // server first so no other device shows it too.
  const celebrate = useCelebrate();
  const [planAtStart] = useState(() => useBilling.getState().checked);
  const streakNow = freeze.on ? freeze.current : data.streak;
  const moment = useTodayMoment({
    loaded: data !== EMPTY && freezeRead !== null,
    today: data.today,
    doneToday: data.doneToday,
    streak: streakNow,
    frozenDays: freeze.frozenDays,
    notebook: data.notebook,
    planAtStart,
    view: celebrate,
  });
  const mainCopy = moment.main;
  const lineCopy = moment.line;
  const [overlayOpen, setOverlayOpen] = useState(true);
  const felt = useRef(false);
  useEffect(() => {
    if (felt.current || moment.pick.main === undefined) return;
    felt.current = true;
    const size = moment.pick.main.size;
    void import('@/features/celebrate/state.js').then((state) => {
      state.feel(size);
    });
  }, [moment.pick.main]);
  const hero = useHeroLines(learn, data, offersRead, {
    ready: !celebrate.on || moment.ready,
    line: lineCopy !== undefined,
  });
  // The Pro trial (features/billing/trial.ts): one card in the slot below
  // the hero, or one line in it, each once, and only once the plan is known.
  const trial = useTrialMoments(data === EMPTY ? null : data.notebook);
  const [trialPaywall, setTrialPaywall] = useState(false);
  // What sits below the card place is drawn once that place is decided
  // (local reads only, a few frames), together with the hero's lines, so a
  // card or a line never arrives after the page under it and pushes it down.
  // A read that never lands must not hide half of Today, hence the bound.
  const [slotSettled, setSlotSettled] = useState(false);
  const [holding, setHolding] = useState(true);
  useEffect(() => {
    const timer = window.setTimeout(() => {
      setHolding(false);
    }, BELOW_HOLD_MS);
    return () => {
      window.clearTimeout(timer);
    };
  }, []);
  const below = (data !== EMPTY && slotSettled && trial.settled && hero.ready) || !holding;

  // Back from a word, a deck or a page lands where the reader was.
  useKeepScroll();
  // Apart from the screen's query, which would otherwise re-run in full on
  // every outbox change for the sake of one dot.
  const queued = useLiveQuery(() => hasQueued(), false, []);
  const name = useAuth((state) => state.user?.displayName);

  const { counts, notebook } = data;
  // The streak chip lifts once when the streak has grown since this device
  // last drew it (a Glint: information, so it stays with celebrations off).
  const chipFrom = celebrate.state?.chip;
  const chipLift = celebrate.on && chipFrom !== undefined && data !== EMPTY && streakNow > chipFrom;
  useEffect(() => {
    if (celebrate.on && celebrate.state !== null && data !== EMPTY && streakNow !== celebrate.state.chip) {
      void noteChip(streakNow);
    }
  }, [celebrate.on, celebrate.state, data, streakNow]);
  // The day as a ring in the hero (done out of done and still due), and
  // "All done for today" once nothing is left: information, not a party.
  const showRing = celebrate.on && counts.total > 0 && data.doneToday + counts.due > 0;
  const fraction = ringFraction(data.doneToday, counts.due);
  const [ringFrom] = useState(() => (ringDrawn.day === data.today ? ringDrawn.fraction : undefined));
  useEffect(() => {
    if (showRing) {
      ringDrawn.day = data.today;
      ringDrawn.fraction = fraction;
    }
  }, [showRing, data.today, fraction]);
  // Under a daily review limit with more due than today has room for, new
  // words wait (SRS v2), so they are not promised here either.
  const total = counts.due + (data.backlog ? 0 : counts.new);
  // The day's limit is reached and nothing missed is left to retry: the
  // session would be empty, so the button walks the notebook instead.
  const capReached = data.backlog && counts.due === 0;
  const canHear = useCanSpeak(notebook?.targetLang ?? 'en');
  // Every word due today is done and nothing new waits: the day's job is over.
  const allDone =
    celebrate.on && counts.total > 0 && total === 0 && data.doneToday > 0 && !data.backlog && data.held === 0;
  const empty = counts.total === 0;

  // Which notebooks the next session draws from. It opens on the setting
  // and can be changed for this session without changing it; a preference
  // is a starting point, not a rule about today.
  // One choice for the whole app, made in the notebook picker. This screen
  // reads it rather than offering a second way to set it: Today and the
  // notebook page disagreeing about what is in view is two answers to one
  // question.
  const scope = data.practiceScope;

  const start = (deck?: string): void => {
    if (empty || (deck === undefined && hero.addWord)) {
      void navigate('/notebook?add=1');
      return;
    }
    const query = new URLSearchParams();
    if (deck !== undefined) query.set('deck', deck);
    else if (capReached) query.set('deck', 'notebook');
    if (scope === 'all') query.set('scope', 'all');
    const search = query.toString();
    void navigate(search === '' ? '/session' : `/session?${search}`);
  };

  const decksTile = {
    key: 'decks',
    icon: 'grid' as IconName,
    tone: styles.tileDecks,
    title: t('today.decksTitle'),
    note: t('today.decksShort', { count: data.topicCount }),
    onClick: () => {
      void navigate('/decks');
    },
  };
  /*
   * With games and drills switched on and fed (SRS v2), two places get rows
   * of their own under the modes: the games (their own screen since
   * 2026-10-09; testers found both rows opening Decks), which nobody found
   * behind "By topic or level", and Decks named for what it holds. They are
   * places rather than modes, so they keep the neutral tint.
   */
  const places =
    games.length === 0
      ? []
      : [
          {
            key: 'games',
            icon: 'grid' as IconName,
            tone: styles.tileDecks,
            title: t('today.gamesTitle'),
            note: t('today.gamesShort', { count: games.length }),
            onClick: () => {
              void navigate(GAMES_PATH);
            },
          },
          ...(data.topicCount > 0
            ? [
                {
                  key: 'decks',
                  icon: 'cards' as IconName,
                  tone: styles.tileDecks,
                  title: t('today.decksTitleAll'),
                  note: t('today.decksShortAll'),
                  onClick: () => {
                    void navigate('/decks');
                  },
                },
              ]
            : []),
        ];

  /*
   * The focused-practice modes that have something in them. Each carries
   * its own count in a short line; the long explanation of what the mode is
   * lives on the screen it opens, not in a tile the size of a stamp.
   */
  const modes: {
    key: string;
    icon: IconName;
    tone: string | undefined;
    title: string;
    note: string;
    onClick: () => void;
  }[] = [
    ...(counts.total > 0 && canHear
      ? [
          {
            key: 'audio',
            icon: 'headphones' as IconName,
            tone: styles.tileAudio,
            title: t('today.audioTitle'),
            note: t('today.audioShort'),
            onClick: () => {
              start('audio');
            },
          },
        ]
      : []),
    ...(counts.struggling > 0
      ? [
          {
            key: 'struggling',
            icon: 'pencil' as IconName,
            tone: styles.tileStruggling,
            title: t('today.strugglingTitle'),
            note: t('today.strugglingShort', { count: counts.struggling }),
            onClick: () => {
              start('struggling');
            },
          },
        ]
      : []),
    ...(counts.starred > 0
      ? [
          {
            key: 'starred',
            icon: 'starOn' as IconName,
            tone: styles.tileStarred,
            title: t('today.starredTitle'),
            note: t('today.starredShort', { count: counts.starred }),
            onClick: () => {
              start('starred');
            },
          },
        ]
      : []),
    ...(counts.confusables > 0
      ? [
          {
            key: 'confusables',
            icon: 'shuffle' as IconName,
            tone: styles.tileConfusable,
            title: t('today.confusablesTitle'),
            note: t('today.confusablesShort', { count: counts.confusables }),
            onClick: () => {
              start('confusables');
            },
          },
        ]
      : []),
    ...(counts.tricky > 0
      ? [
          {
            key: 'tricky',
            icon: 'level' as IconName,
            tone: styles.tileTricky,
            title: t('today.trickyTitle'),
            note: t('today.trickyShort', { count: counts.tricky }),
            onClick: () => {
              start('tricky');
            },
          },
        ]
      : []),
    // Decks sits in the grid as one more tile until the games give it a
    // row of its own below (SRS v2): two places to go, not modes to practise.
    // Held back until the modes have been read, so it never jumps out of the grid.
    // With the new learner's journey on, a notebook too small to cut by
    // topic or level does not offer to (C3).
    ...(data.topicCount > 0 &&
    modesView.ready &&
    games.length === 0 &&
    !(learn.on && counts.total < DECKS_TILE_WORDS)
      ? [decksTile]
      : []),
  ];

  return (
    <main className={styles.screen}>
      <header className={styles.header}>
        {/* The date and the chip share the top line, so the greeting has the
            whole width and stops breaking after the comma. */}
        <div className={styles.headerTop}>
          <span className={styles.date}>
            {dateLabel(now)}
            {queued && (
              // The sync indicator the offline spec asks for. The prototype
              // has no server, so this is the one addition to its header.
              <span className={styles.queued} aria-label={t('state.offlineSaved')} role="img" />
            )}
          </span>
          {/* One slot, two jobs. A new account is learning what the app is
              for, so it gets the list; once that is done the slot becomes
              the streak for good. It sits up here rather than in a row of
              its own: a band across the screen made a small piece of
              housekeeping the second thing on Today. */}
          <div className={styles.headerActions}>
            <StartChip
              streak={
                <StreakChip
                  streak={freeze.on ? freeze.current : data.streak}
                  doneToday={data.streakActive}
                  lift={chipLift}
                  onOpen={() => {
                    // With the feature offered, the sheet opens whether
                    // freeze is on or not: it is how a learner hears of it.
                    if (freeze.on || freeze.offered) setFreezeOpen(true);
                    else void navigate('/progress');
                  }}
                />
              }
            />
            {/* The bell takes the far corner, where a phone's own
                notifications live, and stays out of the slot before it,
                which is the one control with two lives (the list, then the
                streak). */}
            <Bell />
          </div>
        </div>
        <h1 className={styles.greeting}>
          {name === undefined || name === ''
            ? greeting(now)
            : t('today.greetingNamed', { greeting: greeting(now), name })}
        </h1>
      </header>
      {/* Two columns on a large window (the stylesheet): the day's plan
          and what to practise on the left, the ways in and the week on
          the right. On anything narrower both wrappers are
          `display: contents`, so the page is the one column it always was,
          in the same order. */}
      <div className={styles.primary}>
        <VerifyBanner />
        <UpdateBanner />
        <ReminderBanner />

        <section className={styles.hero}>
          <span className={styles.heroSheen} aria-hidden="true" />
          {/* Two tilted cards, drawn rather than loaded, showing a word the
            learner actually saved. Nothing here is invented: an app that
            never chooses vocabulary for anybody should not start doing it
            as decoration, so with an empty notebook the cards are simply
            blank shapes. They are hidden from the reader out loud -- the
            same word is a real row further down the screen. */}
          <span className={styles.heroCards} aria-hidden="true">
            <span className={styles.heroCardBack} />
            <span className={styles.heroCardFront}>
              {data.recent[0] === undefined ? (
                // Nothing saved yet, so the card is drawn as a card rather
                // than left blank: a rule where the word goes and two shorter
                // ones under it. No invented vocabulary, and nothing that
                // looks unfinished.
                <>
                  <span className={cx(styles.heroCardRule, styles.heroCardRuleWord)} />
                  <span className={styles.heroCardRule} />
                  <span className={cx(styles.heroCardRule, styles.heroCardRuleShort)} />
                </>
              ) : (
                <>
                  <span className={styles.heroCardWord} lang={notebook?.targetLang ?? 'en'}>
                    {data.recent[0].headword}
                  </span>
                  <span
                    className={styles.heroCardMeaning}
                    dir={directionOf(notebook?.meaningLang ?? 'fa')}
                    style={fontFor(notebook?.meaningLang ?? 'fa')}
                  >
                    {data.recent[0].meaning}
                  </span>
                </>
              )}
            </span>
          </span>
          <div className={styles.heroText}>
            {/* Which notebook this session draws from, and how long it will
              take. The switcher belongs here rather than on a row of its
              own under the greeting: this is the thing it changes, and a
              whole line of the home screen spent on one small pill was the
              most expensive way to say "English". */}
            <div className={styles.heroTop}>
              <NotebookChip tone="hero" />
              <span className={styles.heroKicker}>{heroKicker(data, total)}</span>
            </div>
            <div className={styles.heroHeadRow}>
              {showRing && <Ring fraction={fraction} from={ringFrom} className={styles.heroRing} />}
              <p className={styles.heroHeadline}>
                {allDone
                  ? t('celebrate.allDoneTitle')
                  : hero.nothingDue
                    ? t('today.headlineNothingDue')
                    : heroHeadline(data, total)}
              </p>
            </div>
            {(allDone ? nextLineOf(data) : hero.nextLine) !== undefined && (
              <p className={styles.heroNext}>{allDone ? nextLineOf(data) : hero.nextLine}</p>
            )}
            {/* Counts, once there is something to count. On an empty account
              they were two large zeroes above "Add your first word", which
              is a lot of space spent saying nothing. */}
            {counts.total > 0 && (
              <div className={styles.heroNumbers}>
                <span className={styles.heroNumber} aria-label={t('today.toReview')}>
                  {counts.due}
                </span>
                <span className={cx(styles.heroUnit, !data.backlog && styles.heroUnitGap)}>
                  {t('today.toReview')}
                </span>
                {!data.backlog && (
                  <>
                    <span className={styles.heroNumber} aria-label={t('today.new')}>
                      {counts.new}
                    </span>
                    <span className={styles.heroUnit}>{t('today.new')}</span>
                  </>
                )}
              </div>
            )}
            {/* SRS v2 daily review limit: the learner's own numbers, never a
                quota — how many today asks about and how many wait. */}
            {data.held > 0 && counts.total > 0 && (
              <p className={styles.heroCap}>
                {counts.due === 0 ? t('schedule.capDone') : t('schedule.capToday', { count: counts.due })}{' '}
                {t('schedule.capWait', { count: data.held })}
              </p>
            )}
            {counts.total === 0 && <p className={styles.heroLine}>{t('today.emptyLine')}</p>}
            {/* One line at most, never beside the daily-limit offer: the
                welcome back after a break, or the first word that came back. */}
            {/* A celebration line (a freeze that saved the streak, an
                anniversary) takes the place before the journey's lines. */}
            {offers.capOffer === undefined && lineCopy !== undefined && (
              <MomentLine copy={lineCopy} tone="hero" className={styles.heroMoment} />
            )}
            {offers.capOffer === undefined && lineCopy === undefined && hero.line !== undefined && (
              <p className={styles.heroCap}>{hero.line}</p>
            )}
            {/* The trial's last days: one line, only where no other line
                stands, and never beside the daily-limit offer. */}
            {hero.quiet && trial.endingLine && trial.running !== undefined && (
              <TrialEndingLine endsAt={trial.running.endsAt} endsAtKey={trial.running.key} now={trial.now} />
            )}
          </div>
          {/* SRS v2: back after a break to a big backlog, the one moment a
              daily limit helps. Once per break, and the learner's own
              number on the page it opens, never a quota. */}
          {offers.capOffer !== undefined && counts.total > 0 && (
            <div className={styles.heroOffer}>
              <p className={styles.heroOfferText}>{t('today.capOffer')}</p>
              <div className={styles.heroOfferActions}>
                <button
                  type="button"
                  className={styles.heroOfferAction}
                  onClick={() => {
                    const last = offers.capOffer;
                    if (last !== undefined) void putCapOfferAway(last);
                    void navigate(`${settingsPath('schedule')}#${SCHEDULE_FOCUS.limits}`);
                  }}
                >
                  {t('today.capOfferAction')}
                </button>
                <button
                  type="button"
                  className={styles.heroOfferQuiet}
                  onClick={() => {
                    const last = offers.capOffer;
                    if (last !== undefined) void putCapOfferAway(last);
                  }}
                >
                  {t('nudge.notNow')}
                </button>
              </div>
            </div>
          )}
          <button
            type="button"
            className={styles.start}
            onClick={() => {
              start();
            }}
          >
            {/* No arrow. "Start session" already says what happens, and an
              arrow tacked onto a button label is decoration. */}
            <span>
              {empty
                ? t('today.addFirstWord')
                : hero.addWord
                  ? t('today.addWord')
                  : total === 0
                    ? t('today.practiseAnyway')
                    : t('today.startSession')}
            </span>
          </button>
        </section>

        {/* A card suggesting another surface, when its moment has come: below
          the day's plan, never above it, and at most one a session. */}
        <NudgeSlot
          onSettle={setSlotSettled}
          lead={{
            pending: !trial.settled,
            node:
              trial.card === undefined ? undefined : (
                <TrialCard
                  kind={trial.card}
                  trial={trial}
                  onSeePro={() => {
                    setTrialPaywall(true);
                  }}
                />
              ),
          }}
          fallback={
            offers.smartInvite && notebook !== undefined ? (
              <SmartInvite
                language={LANGUAGE_NAMES[notebook.targetLang]}
                onSee={() => {
                  void putSmartInviteAway(true);
                  void navigate(`${settingsPath('schedule')}#${SCHEDULE_FOCUS.smart}`);
                }}
                onNotNow={() => {
                  void putSmartInviteAway();
                }}
              />
            ) : undefined
          }
        />

        {below && data.recent.length > 0 && (
          <section className={styles.section}>
            <div className={styles.sectionHead}>
              <h2 className={styles.sectionTitle}>{t('today.latestEntries')}</h2>
              <button
                type="button"
                className={styles.sectionLink}
                onClick={() => {
                  void navigate('/notebook');
                }}
              >
                {t('today.openNotebook')}
              </button>
            </div>
            <div className={styles.strip}>
              {data.recent.slice(0, RECENT_SHOWN).map((word) => (
                <button
                  key={word.id}
                  type="button"
                  className={styles.entry}
                  onClick={() => {
                    void navigate(`/words/${word.id}`);
                  }}
                >
                  <span className={styles.entryMargin} aria-hidden="true" />
                  <span className={styles.entryWord} lang={notebook?.targetLang ?? 'en'}>
                    {word.headword}
                  </span>
                  <span
                    className={styles.entryMeaning}
                    dir={directionOf(notebook?.meaningLang ?? 'fa')}
                    lang={notebook?.meaningLang ?? 'fa'}
                    style={fontFor(notebook?.meaningLang ?? 'fa')}
                  >
                    {word.meaning}
                  </span>
                </button>
              ))}
            </div>
          </section>
        )}

        {below && modes.length + places.length > 0 && (
          <section className={styles.section}>
            <h2 className={styles.sectionTitle}>{t('today.focusedPractice')}</h2>
            {/*
             * One pattern for all of them, in a two-column grid, with the last
             * tile spanning the width when there is an odd number. It used to
             * be two tinted tiles and then a list of rows underneath: with the
             * conditional ones hidden that left a single tile sitting in half a
             * row above a list, which reads as a layout that has gone wrong.
             *
             * A mode with nothing in it is not offered. "0 words that keep
             * falling back to box 1" is an invitation to a session that cannot
             * be built, and there were three of them on an empty account.
             */}
            <div className={styles.tiles}>
              {modes.map((mode, index) => (
                <Tile
                  key={mode.key}
                  icon={mode.icon}
                  tone={mode.tone}
                  // An odd one out fills the row rather than leaving a gap.
                  wide={modes.length % 2 === 1 && index === modes.length - 1}
                  title={mode.title}
                  note={mode.note}
                  onClick={mode.onClick}
                />
              ))}
              {places.map((place) => (
                <Tile
                  key={place.key}
                  icon={place.icon}
                  tone={place.tone}
                  wide
                  title={place.title}
                  note={place.note}
                  onClick={place.onClick}
                />
              ))}
            </div>
          </section>
        )}
      </div>
      <div className={styles.secondary}>
        {below && (
          <>
            <button
              type="button"
              className={styles.aiCard}
              onClick={() => {
                void navigate('/read');
              }}
            >
              <span className={cx(styles.rowIcon, styles.rowIconHero)}>
                <Icon name="sparkles" size={20} weight={1.9} />
              </span>
              <span className={styles.rowText}>
                <span className={styles.rowTitle}>{t('today.aiTitle')}</span>
                <span className={styles.rowNote}>{t('today.aiNote')}</span>
              </span>
              <Icon name="chevronRight" size={16} weight={2} className={styles.chevron} />
            </button>

            <button
              type="button"
              className={styles.teaser}
              onClick={() => {
                void navigate('/progress');
              }}
            >
              <span className={styles.teaserHead}>
                <span className={styles.teaserStarted}>
                  {t('today.started', { done: data.started, total: counts.total })}
                </span>
                <span className={styles.teaserMastered}>
                  {t('today.masteredCount', { count: data.mastered })}
                </span>
              </span>
              <span className={styles.boxBar}>
                {data.boxes.map((count, index) => (
                  <span
                    key={index}
                    className={cx(styles.boxSegment, BOX_CLASS[index])}
                    // A zero box keeps a hairline so the ladder reads as five steps.
                    style={{ flex: Math.max(count, 0.001) }}
                  />
                ))}
              </span>
              <span className={styles.teaserLine}>
                {data.doneToday > 0
                  ? t('today.doneToday', { count: data.doneToday })
                  : t('today.nothingToday')}
              </span>
            </button>

            {counts.total > 0 && (
              <section className={styles.week}>
                <div className={styles.weekHead}>
                  <h2 className={styles.sectionTitle}>{t('today.thisWeek')}</h2>
                  <span className={styles.weekLine}>
                    {data.weekTotal > 0
                      ? t('today.weekCards', { count: data.weekTotal })
                      : t('today.weekNone')}
                  </span>
                </div>
                <div className={styles.weekGrid}>
                  {data.week.slice(-WEEK_DAYS).map((day) => (
                    <div key={day.day} className={styles.day}>
                      <div
                        className={cx(
                          styles.dayBox,
                          freeze.frozenDays.has(day.day) && streakStyles.frozenDay,
                        )}
                        title={freeze.frozenDays.has(day.day) ? t('streakFreeze.frozen') : undefined}
                        style={
                          day.reviewed > 0
                            ? {
                                background: `color-mix(in oklch, var(--accent) ${String(
                                  Math.min(100, Math.round(45 + day.reviewed * 1.4)),
                                )}%, var(--surface2))`,
                              }
                            : undefined
                        }
                      >
                        {day.reviewed > 0 ? day.reviewed : ''}
                        {freeze.frozenDays.has(day.day) && (
                          <span className="sr-only">{t('streakFreeze.frozen')}</span>
                        )}
                      </div>
                      <span className={cx(styles.dayLabel, day.day === data.today && styles.dayLabelToday)}>
                        {WEEKDAYS[new Date(day.day * 86_400_000).getUTCDay()]}
                      </span>
                    </div>
                  ))}
                </div>
              </section>
            )}
          </>
        )}
      </div>
      {trialPaywall && (
        <Upgrade
          onClose={() => {
            setTrialPaywall(false);
          }}
        />
      )}
      {mainCopy !== undefined && moment.pick.main?.size === 'takeover' && overlayOpen && (
        <Suspense fallback={null}>
          <Takeover
            copy={mainCopy}
            action={moment.pick.main.id === 'trialStart' ? t('celebrate.letsGo') : t('celebrate.lovely')}
            onClose={() => {
              setOverlayOpen(false);
            }}
          />
        </Suspense>
      )}
      {mainCopy !== undefined && moment.pick.main?.size === 'toast' && overlayOpen && (
        <Suspense fallback={null}>
          <MomentToast
            copy={mainCopy}
            wide
            onDone={() => {
              setOverlayOpen(false);
            }}
          />
        </Suspense>
      )}
      {lineCopy !== undefined && (
        <Announce
          text={[lineCopy.titleText, lineCopy.lineText].filter((part) => part !== undefined).join('. ')}
        />
      )}
      {freezeOpen && (
        <StreakFreezeSheet
          freeze={freeze}
          onProgress={() => {
            setFreezeOpen(false);
            void navigate('/progress');
          }}
          onClose={() => {
            setFreezeOpen(false);
          }}
        />
      )}
    </main>
  );
}

/**
 * One focused-practice choice, as a tile.
 *
 * Tiles rather than rows for the two that are always offered: a row list
 * makes every option look equally likely, and these two are the ones
 * somebody reaches for without thinking.
 */
function Tile({
  icon,
  tone,
  wide,
  title,
  note,
  onClick,
}: {
  icon: IconName;
  tone: string | undefined;
  wide: boolean;
  title: string;
  note: string;
  onClick: () => void;
}): React.JSX.Element {
  return (
    <button type="button" className={cx(styles.tile, tone, wide && styles.tileWide)} onClick={onClick}>
      <span className={styles.tileIcon}>
        <Icon name={icon} size={20} weight={1.9} />
      </span>
      <span className={styles.tileTitle}>{title}</span>
      <span className={styles.tileNote}>{note}</span>
    </button>
  );
}

/**
 * The streak, in the one state it is actually in.
 *
 * It used to print the number only on a day that had already been
 * practised, so somebody five days in opened the app to a "0 day streak"
 * until they did something — the one message most likely to make them not
 * bother. `effectiveStreak` has already dropped the count to zero when a
 * whole day was missed, so the number it gives is the truth on its own.
 *
 * Three states, because there are three: nothing going yet, something going
 * that today has not yet kept, and something going that today has kept. The
 * middle one is the only urgency this app claims anywhere, and it is real —
 * the streak genuinely ends tonight.
 */
function StreakChip({
  streak,
  doneToday,
  lift = false,
  onOpen,
}: {
  streak: number;
  doneToday: boolean;
  /** The streak grew since this device last drew it: the chip lifts once. */
  lift?: boolean;
  onOpen: () => void;
}): React.JSX.Element {
  const none = streak === 0;
  const atRisk = !none && !doneToday;
  const label = none ? t('today.streakStart') : atRisk ? t('today.streakKeep') : t('today.streak');

  return (
    <button
      type="button"
      className={cx(
        styles.streak,
        none && styles.streakNone,
        atRisk && styles.streakAtRisk,
        doneToday && !none && styles.streakLive,
        lift && !none && styles.streakLift,
      )}
      aria-label={none ? t('today.streakStart') : `${String(streak)} ${label}`}
      onClick={onOpen}
    >
      {/* The flame sits on its own lit disc rather than loose beside the
          number. A streak that is alive today is the one warm thing in the
          header; one that is about to break is outlined, not filled, which
          is the difference you should be able to see without reading. */}
      <span className={styles.flameMark}>
        <Icon name="flame" size={15} className={styles.flame} />
      </span>
      {none ? (
        <span className={styles.streakLabel}>{label}</span>
      ) : (
        <span className={styles.streakText}>
          <span className={styles.streakCount}>{streak}</span>
          <span className={styles.streakLabel}>{label}</span>
        </span>
      )}
    </button>
  );
}

/** One focused-practice row: icon tile, title over a note, chevron. */
/** "Friday, Sep 4", as the prototype writes it. */
function dateLabel(now: Date): string {
  return now.toLocaleDateString('en-US', { weekday: 'long', month: 'short', day: 'numeric' });
}

/** When the next words come back, for a day with nothing left in it. */
function nextLineOf(data: TodayData): string | undefined {
  if (data.nextDue === undefined) return undefined;
  return data.nextDue === data.today + 1
    ? t('today.headlineNextTomorrow')
    : t('today.headlineNextIn', { count: data.nextDue - data.today });
}

/** The line above the counts: the workload, or where the notebook stands. */
function heroKicker(data: TodayData, total: number): string {
  if (data.counts.total === 0) {
    const target = data.notebook?.targetLang ?? 'en';
    const meaning = data.notebook?.meaningLang ?? 'fa';
    return t('today.heroLanguages', {
      target: LANGUAGE_NAMES[target],
      meaning: LANGUAGE_NAMES[meaning],
    });
  }
  if (total === 0) return t('today.heroCaughtUp');
  // The session is capped, so the promise is the session, not the backlog.
  const count = data.sessionCap > 0 ? Math.min(total, data.sessionCap) : total;
  return t('today.heroCards', { count, minutes: Math.max(2, Math.round(count * 0.4)) });
}

/** The one letter the avatar shows, or nothing when there is no name. */
/**
 * The line across the top of the hero: what today is, in three words.
 *
 * It follows the state rather than being one slogan for every day, because
 * a card that says the same thing whether there is work waiting or none
 * left stops being read after a week.
 */
function heroHeadline(data: TodayData, total: number): string {
  if (data.counts.total === 0) return t('today.headlineEmpty');
  if (total === 0) return t('today.headlineClear');
  return t('today.headlineWork');
}

/** What the hero adds for the new learner's journey (SRS v2), all undefined or false with it off. */
interface HeroLines {
  /** Nothing is due and nothing new waits: say so plainly (M5). */
  nothingDue: boolean;
  /** When the next words come back, under that headline (M5). */
  nextLine: string | undefined;
  /** A small notebook with nothing due: the button adds a word instead (M5). */
  addWord: boolean;
  /** The one line above the button: welcome back (M11) or the day-2 line (M6). */
  line: string | undefined;
  /**
   * Settled, and no line of the journey's nor the daily-limit offer is in
   * the hero: room for the trial's one line, which never stands beside them.
   */
  quiet: boolean;
  /** Whether the hero's lines have been decided (local reads only). */
  ready: boolean;
}

/**
 * The hero's lines for the new learner's journey. The welcome back is once
 * per break and the day-2 line once ever; each is held for this visit once
 * shown, and both wait until the offers and the last practice day have
 * been read, so neither appears and is then pushed out by the other.
 */
function useHeroLines(
  learn: ReturnType<typeof useLearn>,
  data: TodayData,
  offersRead: SrsOffers | null,
  /** Today's celebration: whether it is decided, and whether it puts a line in the hero. */
  moment: { ready: boolean; line: boolean },
): HeroLines {
  const { counts } = data;
  const lastRead = useLiveQuery<{ day: number | undefined } | null>(
    async () => (learn.on ? { day: await lastPractisedBefore(data.today) } : null),
    null,
    [learn.on, data.today],
  );
  const tips = learn.on ? learn.tips : null;
  const settled = tips !== null && offersRead !== null && lastRead !== null;
  const capOffer = offersRead?.capOffer !== undefined;

  // A celebration line takes the hero's one line: the welcome back and the
  // day-2 tip wait for a later visit and are not marked shown.
  const wantsBack =
    settled &&
    moment.ready &&
    !moment.line &&
    !tips.off &&
    data.doneToday === 0 &&
    wantsComeback({
      today: data.today,
      lastPractised: lastRead.day,
      due: counts.due,
      capOffer,
      shownFor: tips.comeback,
    });
  const [back, setBack] = useState<number | undefined>(undefined);
  if (wantsBack && back === undefined && lastRead.day !== undefined) setBack(lastRead.day);
  useEffect(() => {
    if (back !== undefined) void markComeback(back);
  }, [back]);

  const pick =
    settled && moment.ready && !moment.line && back === undefined && !capOffer
      ? pickTip('today', { today: data.today, wants: { firstReturn: counts.due > 0 } }, tips)
      : undefined;
  // Held for this visit to this notebook: switching notebooks is a new
  // moment, so a line about the last one's words never stays on the next.
  const tip = useHeldTip(pick, `today:${data.notebook?.id ?? ''}`);

  const nothingDue =
    learn.on && counts.total > 0 && counts.due === 0 && counts.new === 0 && !data.backlog && data.held === 0;
  const nextLine = !nothingDue
    ? undefined
    : data.nextDue === data.today + 1
      ? t('today.headlineNextTomorrow')
      : data.nextDue !== undefined
        ? t('today.headlineNextIn', { count: data.nextDue - data.today })
        : undefined;
  // Each line only while it is still true of what the hero shows.
  const line =
    back !== undefined && counts.due > 0
      ? t('today.comeback')
      : tip !== undefined && counts.due > 0
        ? t(`tip.${tip}`)
        : undefined;
  return {
    nothingDue,
    nextLine,
    addWord: nothingDue && counts.total < SMALL_NOTEBOOK_WORDS,
    line,
    quiet:
      learn.ready &&
      offersRead !== null &&
      !capOffer &&
      (!learn.on || settled) &&
      moment.ready &&
      !moment.line &&
      line === undefined,
    ready: learn.ready && offersRead !== null && (!learn.on || settled) && moment.ready,
  };
}

/**
 * The trial's "ends on" line in the hero, marked shown once it is on screen
 * (and held there for this run of the app), so it is said once.
 */
function TrialEndingLine({
  endsAt,
  endsAtKey,
  now,
}: {
  endsAt: Date;
  endsAtKey: string;
  now: Date;
}): React.JSX.Element {
  useEffect(() => {
    markTrialEndingShown(endsAtKey);
  }, [endsAtKey]);
  return <p className={styles.heroCap}>{t('trial.ending', { date: trialDate(endsAt, now) })}</p>;
}

/** Persian and Arabic meanings need their own face to stay readable. */
function fontFor(lang: LanguageCode): React.CSSProperties | undefined {
  return lang === 'fa' || lang === 'ar' ? { fontFamily: 'var(--fa)' } : undefined;
}
