/**
 * The bell on Today: what the server has said to this account.
 *
 * The server is the record (it writes a row for every announcement, gift and
 * come-back note, whether or not a phone or browser showed a pop-up). This
 * keeps a copy of the newest page in IndexedDB meta, so the bell draws from
 * local data on the first frame, and refreshes it when Today opens and when
 * the app comes back to the foreground.
 */
import { inbox as inboxApi } from '@/api/endpoints.js';
import { db, getMeta, setMeta, type InboxNotification, type MetaShape } from '@/db/schema.js';
import { notificationFromApi } from '@/sync/mapping.js';

/**
 * How many notifications the sheet lists: the newest page and no more. The
 * server keeps ninety days, and a bell is for what is recent; anything older
 * than a page is not what somebody opens it to find. A constant because it is
 * a choice about this screen, and it must stay within the contract's `Limit`
 * (contract.test.ts reads that bound).
 */
export const INBOX_PAGE = 30;

type Inbox = NonNullable<MetaShape['inbox']>;

/**
 * Ids marked read here whose call has not come back yet. A refresh that lands
 * in between must not bring them back as unread.
 */
const pending = new Set<string>();

let inFlight: Promise<boolean> | undefined;

/** Applies this device's reads that the server may not have seen yet. */
function withPending(inbox: Inbox): Inbox {
  if (pending.size === 0) return inbox;
  const now = new Date().toISOString();
  let cleared = 0;
  const notifications = inbox.notifications.map((item) => {
    if (item.readAt !== undefined || !pending.has(item.id)) return item;
    cleared++;
    return { ...item, readAt: now };
  });
  return { notifications, unread: Math.max(0, inbox.unread - cleared) };
}

/**
 * Reads the newest page from the server into the local copy. Resolves true
 * when it did, false when the server could not be reached; a failure leaves
 * the copy as it was. Two calls at once share one request.
 */
export function refreshInbox(): Promise<boolean> {
  inFlight ??= inboxApi
    .list({ limit: INBOX_PAGE })
    .then(async (page) => {
      await setMeta(
        'inbox',
        withPending({ notifications: page.notifications.map(notificationFromApi), unread: page.unread }),
      );
      return true;
    })
    .catch(() => false)
    .finally(() => {
      inFlight = undefined;
    });
  return inFlight;
}

/**
 * Marks notifications read: at once in the local copy, so the dot goes out
 * without waiting, then on the server. If the call fails they come back as
 * unread on the next refresh, which is the truth.
 */
export async function markInboxRead(ids: readonly string[]): Promise<void> {
  if (ids.length === 0) return;
  for (const id of ids) pending.add(id);
  await db.transaction('rw', db.meta, async () => {
    const current = await getMeta('inbox');
    if (current !== null) await setMeta('inbox', withPending(current));
  });
  try {
    await inboxApi.markRead([...ids]);
  } catch {
    // Offline or refused: the server still has them unread, and says so next time.
  } finally {
    for (const id of ids) pending.delete(id);
  }
}

/** The ones not yet read, newest first as the server sent them. */
export function unreadIds(items: readonly InboxNotification[]): string[] {
  return items.filter((item) => item.readAt === undefined).map((item) => item.id);
}
