import { Icon } from '@/components/ui/Icon.js';
import { t } from '@/i18n/index.js';
import styles from '@/features/everywhere/NudgeCard.module.css';
import own from './SmartInvite.module.css';

/**
 * The one card on Today that tells a learner Smart exists (SRS v2 access
 * proposal 3). Smart is Beta and opt-in, so this invites and never pushes:
 * it is shown once, only with enough history for Smart to work from
 * (`loadSrsOffers`), and promises no numbers. "See how it works" opens the
 * schedule page with Smart in focus, not switched; either button puts the
 * card away for good. It wears the house card for suggestions (the nudge
 * card's shape) and takes that card's place, so Today never shows both.
 */
export function SmartInvite({
  language,
  onSee,
  onNotNow,
}: {
  /** The notebook's language, by name. */
  language: string;
  onSee: () => void;
  onNotNow: () => void;
}): React.JSX.Element {
  return (
    <aside className={styles.card} aria-labelledby="smart-invite-title">
      <div className={styles.head}>
        <span className={styles.icon} aria-hidden="true">
          <Icon name="sparkles" size={20} weight={1.9} />
        </span>
        <span className={styles.text}>
          <h2 id="smart-invite-title" className={styles.title}>
            {t('today.smartTitle')} <span className={own.beta}>{t('schedule.beta')}</span>
          </h2>
          <p className={styles.line}>{t('today.smartLine', { language })}</p>
        </span>
      </div>
      <div className={styles.actions}>
        <button type="button" className={styles.primary} onClick={onSee}>
          {t('today.smartSee')}
        </button>
        <button type="button" className={styles.quiet} onClick={onNotNow}>
          {t('nudge.notNow')}
        </button>
      </div>
    </aside>
  );
}
