import { MAX_FREEZES, FREEZE_EVERY } from '@lexpad/core';
import { Icon } from '@/components/ui/Icon.js';
import { Sheet } from '@/components/ui/Sheet.js';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import type { FreezeView } from './data.js';
import { useFreezeSwitch } from './useFreezeSwitch.js';
import styles from './Streak.module.css';

/**
 * What the streak chip opens while streak freeze is on: the streak, the
 * freezes ready, and the way to Progress the chip used to be. Freezes are
 * earned by practice and never bought, so there is nothing here to buy.
 *
 * While the feature is offered but freeze is off, the same sheet says that
 * freezes exist and offers to turn them on (SRS v2 access proposal 4): until
 * then nothing told a learner about them before a streak was lost. Once
 * turned on, the sheet becomes the usual one in place.
 */
export function StreakFreezeSheet({
  freeze,
  onProgress,
  onClose,
}: {
  freeze: FreezeView;
  onProgress: () => void;
  onClose: () => void;
}): React.JSX.Element {
  // One sheet whichever it says, so turning freeze on changes its words in
  // place rather than closing it and opening another.
  return (
    <Sheet title={t('streakFreeze.title')} onClose={onClose}>
      {freeze.on ? (
        <FreezeOn freeze={freeze} onProgress={onProgress} />
      ) : (
        <FreezeOffer freeze={freeze} onProgress={onProgress} />
      )}
    </Sheet>
  );
}

/** The sheet's words while freeze is on: the streak and the freezes ready. */
function FreezeOn({ freeze, onProgress }: { freeze: FreezeView; onProgress: () => void }): React.JSX.Element {
  return (
    <div className={styles.sheet}>
      <div className={styles.head}>
        <span className={styles.flame} aria-hidden="true">
          <Icon name="flame" size={22} />
        </span>
        <p className={styles.count}>{t('streakFreeze.streak', { count: freeze.current })}</p>
      </div>
      <div className={styles.freezes} aria-hidden="true">
        {Array.from({ length: MAX_FREEZES }, (_, index) => (
          <span key={index} className={cx(styles.freeze, index < freeze.freezes && styles.freezeReady)}>
            {index < freeze.freezes && <Icon name="check" size={16} weight={2.2} />}
          </span>
        ))}
      </div>
      <p className={styles.line} role="status">
        {freeze.freezes > 0
          ? t('streakFreeze.ready', { count: freeze.freezes })
          : t('streakFreeze.none', { days: FREEZE_EVERY })}
      </p>
      <button type="button" className={styles.action} onClick={onProgress}>
        {t('streakFreeze.seeProgress')}
      </button>
    </div>
  );
}

/** The sheet while freeze is off: the streak, one line about freezes, and the switch as a button. */
function FreezeOffer({
  freeze,
  onProgress,
}: {
  freeze: FreezeView;
  onProgress: () => void;
}): React.JSX.Element {
  const { ready, online, saving, older, status, failed, change } = useFreezeSwitch();
  return (
    <div className={styles.sheet}>
      <div className={styles.head}>
        <span className={styles.flame} aria-hidden="true">
          <Icon name="flame" size={22} />
        </span>
        <p className={styles.count}>
          {freeze.current > 0 ? t('streakFreeze.streak', { count: freeze.current }) : t('today.streakStart')}
        </p>
      </div>
      <p className={styles.line}>{t('streakFreeze.offer', { days: FREEZE_EVERY })}</p>
      {!ready ? null : older ? (
        // An older app of the account would show a broken streak: the
        // button waits, and the line says why.
        <p className={styles.note}>{t('streakFreeze.olderDevices')}</p>
      ) : (
        <button
          type="button"
          className={styles.primary}
          disabled={saving || !online}
          onClick={() => {
            void change(true);
          }}
        >
          {t('streakFreeze.turnOn')}
        </button>
      )}
      {ready && !online && !older && <p className={styles.note}>{t('streakFreeze.offline')}</p>}
      {status !== undefined && status !== '' && (
        <p className={cx(styles.note, failed && styles.noteError)} role="status">
          {status}
        </p>
      )}
      <button type="button" className={styles.action} onClick={onProgress}>
        {t('streakFreeze.seeProgress')}
      </button>
    </div>
  );
}
