import { useState } from 'react';
import type { ApiNudgeId } from '@/api/types.js';
import { Icon, type IconName } from '@/components/ui/Icon.js';
import { t, type MessageKey } from '@/i18n/index.js';

import styles from './NudgeCard.module.css';

/** What the card's main button does. */
export type NudgeAction =
  { kind: 'link'; href: string; label: MessageKey } | { kind: 'button'; label: MessageKey; run: () => void };

const ICONS: Record<ApiNudgeId, IconName> = {
  extension: 'grid',
  desktop_safari: 'grid',
  desktop_power: 'grid',
  on_your_computer: 'grid',
  on_your_phone: 'cards',
  android_browser: 'cards',
  connector: 'sparkles',
  kindle: 'notebook',
};

/**
 * One card on Today that suggests another surface: what it is for, the one
 * action that gets it, "Not now", and "Don't show again" behind the ⋯. No
 * modal and no countdown; it sits in the page like any other card.
 */
export function NudgeCard({
  id,
  action,
  note,
  onAct,
  onNotNow,
  onNever,
}: {
  id: ApiNudgeId;
  action: NudgeAction;
  /** A line under the buttons, such as "Link copied". */
  note?: string | undefined;
  onAct: () => void;
  onNotNow: () => void;
  onNever: () => void;
}): React.JSX.Element {
  const [menu, setMenu] = useState(false);
  const titleId = `nudge-${id}`;
  return (
    <aside className={styles.card} aria-labelledby={titleId}>
      <div className={styles.head}>
        <span className={styles.icon} aria-hidden="true">
          <Icon name={ICONS[id]} size={20} weight={1.9} />
        </span>
        <span className={styles.text}>
          <h2 id={titleId} className={styles.title}>
            {t(`nudge.${id}.title` as MessageKey)}
          </h2>
          <p className={styles.line}>{t(`nudge.${id}.line` as MessageKey)}</p>
        </span>
        <button
          type="button"
          className={styles.more}
          aria-label={t('nudge.more')}
          aria-expanded={menu}
          onClick={() => {
            setMenu((open) => !open);
          }}
        >
          <Icon name="more" size={18} weight={2} />
        </button>
      </div>
      <div className={styles.actions}>
        {menu ? (
          <button type="button" className={styles.quiet} onClick={onNever}>
            {t('nudge.never')}
          </button>
        ) : (
          <>
            {action.kind === 'link' ? (
              <a
                className={styles.primary}
                href={action.href}
                target="_blank"
                rel="noopener noreferrer"
                onClick={onAct}
              >
                {t(action.label)}
              </a>
            ) : (
              <button
                type="button"
                className={styles.primary}
                onClick={() => {
                  onAct();
                  action.run();
                }}
              >
                {t(action.label)}
              </button>
            )}
            <button type="button" className={styles.quiet} onClick={onNotNow}>
              {t('nudge.notNow')}
            </button>
          </>
        )}
      </div>
      {note !== undefined && (
        <p className={styles.note} role="status">
          {note}
        </p>
      )}
    </aside>
  );
}
