import { useEffect, useState } from 'react';
import { Icon } from '@/components/ui/Icon.js';
import { getMeta } from '@/db/schema.js';
import { t } from '@/i18n/index.js';
import { useLiveQuery } from '@/lib/useLiveQuery.js';
import { GetStarted } from './GetStarted.js';
import { decideOnce, progress } from './steps.js';
import styles from './StartChip.module.css';

/**
 * The top-right slot on Today: the getting-started list while there is one
 * to finish, and the streak for ever after.
 *
 * Handing the slot over rather than adding a second one is the point. A new
 * account has no streak, so that chip could only ever say "Build a streak" —
 * an invitation with nothing behind it. The list goes there instead, and
 * when it is finished the streak takes the slot back, which is also when
 * there is finally a streak worth showing.
 *
 * An account that already has words and a practice history never sees the
 * list at all: it is not new, and telling somebody who has used the app for
 * a month to add their first word would be the app failing to notice them.
 */
export function StartChip({ streak }: { streak: React.ReactNode }): React.JSX.Element {
  const [open, setOpen] = useState(false);
  // Settled once, in an effect rather than in the live query below: the
  // decision writes, and a write inside a live query retriggers it.
  useEffect(() => {
    void decideOnce();
  }, []);
  const decided = useLiveQuery(() => getMeta('getStarted'), undefined, []);
  const here = useLiveQuery(() => progress(), undefined, []);

  // Undefined or null means the decision has not landed yet. The streak is
  // the safe thing to show meanwhile: it is what the slot held before this
  // existed, so nothing flickers into view and back out.
  if (decided?.offered !== true || here === undefined || here.complete) return <>{streak}</>;

  return (
    <>
      <button
        type="button"
        className={styles.chip}
        aria-label={`${t('start.chip')}, ${t('start.progress', { done: here.count, total: here.total })}`}
        onClick={() => {
          setOpen(true);
        }}
      >
        <Ring done={here.count} total={here.total} />
        <span className={styles.text}>
          <span className={styles.label}>{t('start.chip')}</span>
          <span className={styles.count}>{t('start.progress', { done: here.count, total: here.total })}</span>
        </span>
        <Icon name="chevronRight" size={14} weight={2} className={styles.go} />
      </button>
      {open && (
        <GetStarted
          onClose={() => {
            setOpen(false);
          }}
        />
      )}
    </>
  );
}

/** How far along, as a ring rather than a number the eye has to read. */
function Ring({ done, total }: { done: number; total: number }): React.JSX.Element {
  const radius = 9;
  const circumference = 2 * Math.PI * radius;
  const filled = total === 0 ? 0 : (done / total) * circumference;
  return (
    <svg className={styles.ring} viewBox="0 0 24 24" aria-hidden="true">
      <circle className={styles.ringTrack} cx="12" cy="12" r={radius} />
      <circle
        className={styles.ringFill}
        cx="12"
        cy="12"
        r={radius}
        strokeDasharray={`${String(filled)} ${String(circumference)}`}
      />
    </svg>
  );
}
