import { useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Icon } from '@/components/ui/Icon.js';
import { t } from '@/i18n/index.js';
import { trialDate, type TrialCardKind } from '@/features/billing/trial.js';
import styles from '@/features/everywhere/NudgeCard.module.css';
import { markTrialCardShown, type TrialMoments } from './useTrial.js';

/**
 * The Pro trial's one card on Today (`marketing/research/2026-10-free-vs-pro.md`,
 * section 5), in the house shape for suggestions. Midway it says Pro is
 * here until a date and offers one thing to try with the learner's own
 * words — what Words worth keeping finds in a text, for somebody who has
 * pasted one, or Lex otherwise. After the end it says what stays, the Lex
 * questions asked if there were any, and offers Pro. Either button, or Not
 * now, puts it away for good; being on screen once is what makes it once.
 *
 * No number of allowances, no countdown and no claim the server cannot
 * stand behind: the words kept from texts are not counted anywhere, so they
 * are not mentioned.
 */
export function TrialCard({
  kind,
  trial,
  onSeePro,
}: {
  kind: TrialCardKind;
  trial: TrialMoments;
  /**
   * Opens the paywall. It lives with the screen rather than the card: the
   * card is put away by the same tap, and a purchase that goes through
   * takes the account off Free, so a sheet inside the card would close
   * under the learner mid-purchase.
   */
  onSeePro: () => void;
}): React.JSX.Element | null {
  const navigate = useNavigate();
  const endedKey = trial.ended?.key;

  useEffect(() => {
    markTrialCardShown(kind, endedKey);
  }, [kind, endedKey]);

  const titleId = `trial-${kind}`;

  if (kind === 'midway') {
    const running = trial.running;
    if (running === undefined) return null;
    const action = trial.pasted
      ? { label: t('trial.midwayRead'), to: '/read' }
      : { label: t('trial.midwayLex'), to: '/assistant' };
    return (
      <aside className={styles.card} aria-labelledby={titleId}>
        <div className={styles.head}>
          <span className={styles.icon} aria-hidden="true">
            <Icon name="sparkles" size={20} weight={1.9} />
          </span>
          <span className={styles.text}>
            <h2 id={titleId} className={styles.title}>
              {t('trial.midwayTitle', { date: trialDate(running.endsAt, trial.now) })}
            </h2>
            <p className={styles.line}>{t('trial.midwayLine')}</p>
          </span>
        </div>
        <div className={styles.actions}>
          <button
            type="button"
            className={styles.primary}
            onClick={() => {
              trial.answer('midway');
              void navigate(action.to);
            }}
          >
            {action.label}
          </button>
          <button
            type="button"
            className={styles.quiet}
            onClick={() => {
              trial.answer('midway');
            }}
          >
            {t('nudge.notNow')}
          </button>
        </div>
      </aside>
    );
  }

  const asked = trial.ended?.lexQuestions ?? 0;
  return (
    <aside className={styles.card} aria-labelledby={titleId}>
      <div className={styles.head}>
        <span className={styles.icon} aria-hidden="true">
          <Icon name="notebook" size={20} weight={1.9} />
        </span>
        <span className={styles.text}>
          <h2 id={titleId} className={styles.title}>
            {t('trial.endedTitle')}
          </h2>
          <p className={styles.line}>
            {t('trial.endedLine')}
            {asked > 0 && <> {t('trial.endedLex', { count: asked })}</>}
          </p>
        </span>
      </div>
      <div className={styles.actions}>
        <button
          type="button"
          className={styles.primary}
          onClick={() => {
            trial.answer('ended');
            onSeePro();
          }}
        >
          {t('pro.see')}
        </button>
        <button
          type="button"
          className={styles.quiet}
          onClick={() => {
            trial.answer('ended');
          }}
        >
          {t('nudge.notNow')}
        </button>
      </div>
    </aside>
  );
}
